<?php
namespace App\Domain\CaseStudies; use App\Domain\PublicChrome\PublicAssetPath; use App\Models\CaseStudy; use Illuminate\Support\Facades\Cache; use Throwable; final class CaseStudyIndexViewData { public function get(int $page,?int $client=null,?int $industry=null):array{try{return Cache::remember('public.case-studies.index.v1.'.CaseStudyCache::indexVersion().'.'.now()->format('YmdHi').".$page.$client.$industry",now()->addMinutes(10),fn()=>$this->load($page,$client,$industry));}catch(Throwable){return $this->load($page,$client,$industry);}} private function load(int $page,?int $client,?int $industry):array{$p=CaseStudy::publiclyVisible()->with('client')->when($client,fn($q)=>$q->where('client_id',$client))->when($industry,fn($q)=>$q->whereHas('relatedIndustries',fn($i)=>$i->whereKey($industry)))->orderByDesc('is_featured')->orderBy('display_order')->paginate(12,['*'],'page',$page);return ['items'=>$p->getCollection()->map(fn($x)=>['title'=>$x->title,'description'=>$x->short_description,'client'=>$x->client?->isPubliclyVisible()?$x->client->name:null,'image'=>PublicAssetPath::isSafe($x->featured_image_path)?$x->featured_image_path:null,'image_alt'=>$x->featured_image_alt,'url'=>route('case-studies.show',$x->slug)])->all(),'pagination'=>['last'=>$p->lastPage(),'previous'=>$p->previousPageUrl(),'next'=>$p->nextPageUrl()]];} }
